long long comb(int n, int k) {
    if (k < 0 || k > n) return 0;
    long long num = 1, den = 1;
    for (int i = 1; i <= k; i++) {
        num = (num * (n - i + 1)) % MOD;
        den = (den * i) % MOD;
    }
    return (num * modpow(den, MOD - 2)) % MOD;
}

