#include <stdio.h>

#define MOD 1000000007LL

long long mod_pow(long long a, long long e) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    long long n, k;
    if (scanf("%lld %lld", &n, &k) != 2) return 0;

    /* 
       After k moves, compared to the initial state, each move decreases one room by 1
       and increases another room by 1. So the final distribution x1+...+xn = n,
       xi >= 0.

       Any distribution is reachable in at most n-1 moves:
       gather everyone into one room, then redistribute.

       Also parity matters:
       Let d = sum_i max(0, xi-1). This is the minimum number of moves needed.
       Any extra 2 moves can be wasted by moving one person forth and back.
       Hence a distribution is reachable after exactly k moves iff d <= k and d ≡ k (mod 2).

       Since d = number of "incoming" moves needed, distributions with d = t are exactly
       solutions of y1+...+yn = t, yi >= 0, where yi = max(0, xi-1) contribution-wise,
       equivalently number of distributions of n+t? More directly:
       Starting from xi initially 1, after t net incoming moves arrangement count equals
       number of integer vectors with sum n and total positive excess t, which is same as
       choosing t indistinguishable additions among n rooms:
           C(n+t-1, t)

       Therefore answer = sum over t <= k, t ≡ k (mod 2) of C(n+t-1, t).
       Using hockey-stick on same parity:
           sum_{j=0..m} C(n + (k-2j) -1, k-2j)
       We compute directly in O(k), which is acceptable for moderate constraints.
    */

    long long maxN = n + k;
    long long fact[maxN + 1];
    long long invfact[maxN + 1];

    fact[0] = 1;
    for (long long i = 1; i <= maxN; i++) fact[i] = fact[i - 1] * i % MOD;

    invfact[maxN] = mod_pow(fact[maxN], MOD - 2);
    for (long long i = maxN; i > 0; i--) invfact[i - 1] = invfact[i] * i % MOD;

    long long ans = 0;
    for (long long t = k % 2; t <= k; t += 2) {
        long long comb = fact[n + t - 1];
        comb = comb * invfact[t] % MOD;
        comb = comb * invfact[n - 1] % MOD;
        ans += comb;
        if (ans >= MOD) ans -= MOD;
    }

    printf("%lld\n", ans % MOD);
    return 0;
}

