int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, k;
    cin >> n >> k;

    // After exactly k moves, total people count stays n, and each move changes
    // the occupancy vector by moving 1 from one room to another.
    //
    // Starting from (1,1,...,1), after k moves we can reach exactly those
    // distributions x1+...+xn=n with sum of positive increments equal to
    // sum of deficits = t, where 0 <= t <= k and parity(t) = parity(k).
    //
    // Let y_i = x_i - 1, then sum y_i = 0 and
    //   t = sum_{y_i>0} y_i = (1/2) * sum |y_i|.
    //
    // For fixed t, choose:
    // - p rooms that are above 1, contributing positive integers summing to t
    // - q rooms that are below 1 (thus become 0), each contributes exactly 1 deficit
    //   because initial value is 1, so q rooms are chosen among remaining rooms and q <= t
    //
    // More directly, count distributions with exactly s empty rooms.
    // Then among remaining n-s rooms, values are positive and sum to n.
    // Let z_i >= 1 for those rooms. Relative to all-ones, total excess on non-empty rooms is s,
    // so the minimum number of moves needed is s, and any larger number with same parity is possible
    // by adding back-and-forth moves.
    //
    // Hence reachable after exactly k moves iff number of empty rooms s satisfies:
    //   0 <= s <= min(n-1, k) and s % 2 == k % 2
    //
    // For fixed s:
    // - choose which s rooms are empty: C(n, s)
    // - distribute n people into n-s non-empty rooms: number of positive solutions
    //   x1+...+x_{n-s}=n is C(n-1, n-s-1) = C(n-1, s)
    //
    // Total = sum C(n,s) * C(n-1,s) over valid s.

    int N = (int)n;
    vector<long long> fact(N + 1), invfact(N + 1);
    fact[0] = 1;
    for (int i = 1; i <= N; ++i) fact[i] = fact[i - 1] * i % MOD;
    invfact[N] = mod_pow(fact[N], MOD - 2);
    for (int i = N; i > 0; --i) invfact[i - 1] = invfact[i] * i % MOD;

    auto C = [&](int a, int b) -> long long {
        if (b < 0 || b > a) return 0;
        return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD;
    };

    long long ans = 0;
    for (int s = (int)(k & 1); s <= min<long long>(n - 1, k); s += 2) {
        ans = (ans + C((int)n, s) * C((int)n - 1, s)) % MOD;
    }

    cout << ans % MOD << '\n';
    return 0;
}

import java.util.Scanner;

public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        sc.close();

        // dp[s][d] = ways to have sum s and total absolute deviation d
        int[][] dp = new int[n + 1][2 * n + 1];
        dp[0][0] = 1;

        for (int room = 0; room < n; room++) {
            int[][] next = new int[n + 1][2 * n + 1];
            for (int s = 0; s <= n; s++) {
                for (int d = 0; d <= 2 * n; d++) {
                    if (dp[s][d] == 0) continue;
                    for (int x = 0; x <= n - s; x++) {
                        int newD = d + Math.abs(x - 1);
                        next[s + x][newD] = (next[s + x][newD] + dp[s][d]) % MOD;
                    }
                }
            }
            dp = next;
        }

        long ans = 0;
        for (int d = 0; d <= 2 * n; d++) {
            if (d % 2 == 0) {
                int movesNeeded = d / 2;
                if (k >= movesNeeded && (k - movesNeeded) % 2 == 0) {
                    ans = (ans + dp[n][d]) % MOD;
                }
            }
        }
        System.out.println(ans);
    }
}

