        int n = sc.nextInt(), k = sc.nextInt();
        long[] fact = new long[n+1], inv_fact = new long[n+1];
        fact[0]=1; for(int i=1;i<=n;i++) fact[i]=fact[i-1]*i%MOD;
        inv_fact[n]=modpow(fact[n],MOD-2,MOD);
        for(int i=n-1;i>=0;i--) inv_fact[i]=inv_fact[i+1]*(i+1)%MOD;
        long ans=0;
        for(int s=0;s<=n;s++){
            int m=n-s;
            if(m>k||(k-m)%2!=0) continue;
            long comb=fact[n]%MOD*inv_fact[s]%MOD*inv_fact[m]%MOD;
            // f(m,n): functions from m elements to n with no fixed point
            long fm=0;
            for(int j=0;j<=m;j++){
                long term=fact[m]%MOD*inv_fact[j]%MOD*inv_fact[m-j]%MOD*modpow(n,m-j,MOD)%MOD;
                if(j%2==0) fm=(fm+term)%MOD; else fm=(fm-term+MOD)%MOD;
            }
            ans=(ans+comb*fm)%MOD;
        }
        System.out.println(ans);
    }
    static long modpow(long b,long e,long m){long r=1;b%=m;while(e>0){if((e&1)==1)r=r*b%m;b=b*b%m;e>>=1;}return r;}
}

