import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long n = fs.nextLong();
        long k = fs.nextLong();

        // Number of distributions of n indistinguishable people into n rooms
        // after k moves is the number of integer vectors:
        // x1 + x2 + ... + xn = n, xi >= 0
        // reachable in exactly k moves from initial (1,1,...,1).
        //
        // Each move changes two rooms by (-1, +1), so total sum stays n.
        // Also, one move can increase L1 distance from initial state by 2,
        // hence exactly k moves means reachable states are those with
        // sum |xi - 1| <= 2k and same parity, which is equivalent to
        // number of people staying in original "baseline" allowing at most k transfers.
        //
        // This simplifies to counting nonnegative solutions of:
        // y1 + ... + yn = t, yi >= 0, where t ranges from 0..min(k, n-1?) ?
        //
        // In fact any distribution can be reached in exactly k moves iff
        // minimal number of moves needed is <= k, where minimal moves equals
        // sum max(0, xi - 1) = (1/2) * sum |xi - 1|.
        // So we count vectors with sum xi = n and excess <= k.
        //
        // Let m = number of rooms with xi = 0 / deficits balanced by excess.
        // Standard transformation:
        // minimal moves = number of people moved = s.
        // Choose final occupancies by starting from 1 in each room and distributing
        // s extra people among n rooms while creating s empty spots among rooms.
        //
        // Equivalent count of reachable states after at most k moves from all-ones
        // is C(n + k - 1, k) for k < n, and all states C(2n - 1, n) once k >= n-1.
        //
        // More directly, the number of states reachable in exactly k moves equals
        // number reachable in at most k moves, because redundant back-and-forth moves
        // can be inserted. Thus answer is:
        // sum_{s=0}^{min(k, n-1)} C(n, s) * C(n-1, s)
        //
        // By Vandermonde identity:
        // sum_{s=0}^{min(k,n-1)} C(n,s)C(n-1,s) = C(2n-1, n-1) for k >= n-1,
        // otherwise partial sum.
        //
        // We compute the partial sum in O(min(k,n)).

        long limit = Math.min(k, n - 1);
        Comb comb = new Comb((int)(2 * n + 5), MOD);

        long ans = 0;
        for (int s = 0; s <= limit; s++) {
            ans += comb.c((int)n, s) * comb.c((int)(n - 1), s) % MOD;
            if (ans >= MOD) ans -= MOD;
        }

        System.out.println(ans % MOD);
    }

    static class Comb {
        long[] fact, invFact;
        int max;
        long mod;

        Comb(int n, long mod) {
            this.max = n;
            this.mod = mod;
            fact = new long[n + 1];
            invFact = new long[n + 1];
            fact[0] = 1;
            for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % mod;
            invFact[n] = modPow(fact[n], mod - 2, mod);
            for (int i = n; i > 0; i--) invFact[i - 1] = invFact[i] * i % mod;
        }

        long c(int n, int r) {
            if (r < 0 || r > n) return 0;
            return fact[n] * invFact[r] % mod * invFact[n - r] % mod;
        }

        static long modPow(long a, long e, long mod) {
            long res = 1 % mod;
            a %= mod;
            while (e > 0) {
                if ((e & 1) == 1) res = res * a % mod;
                a = a * a % mod;
                e >>= 1;
            }
            return res;
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

