def solve():
    import sys
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    n = int(input_data[0])
    k = int(input_data[1])

    # dp[deviation] = number of ways for processed rooms
    dp = [0] * (k + 1)
    dp[0] = 1

    for room in range(n):
        new_dp = [0] * (k + 1)
        for d in range(k + 1):
            if dp[d] == 0:
                continue
            # assign x people to this room
            for x in range(0, n + 1):
                nd = d + max(0, x - 1)
                if nd > k:
                    break
                new_dp[nd] = (new_dp[nd] + dp[d]) % MOD
        dp = new_dp

    # We need exactly n total people placed, but we always place n over n rooms.
    # We didn't track total sum; we need to fix that.
    # Better approach: DP over rooms and total sum.

    # Let's redo properly:
    dp2 = [[0]*(k+1) for _ in range(n+1)]
    dp2[0][0] = 1
    for room in range(n):
        new = [[0]*(k+1) for _ in range(n+1)]
        for s in range(n+1):
            for d in range(k+1):
                if dp2[s][d] == 0:
                    continue
                for x in range(0, n - s + 1):
                    nd = d + max(0, x - 1)
                    if nd > k:
                        break
                    new[s+x][nd] = (new[s+x][nd] + dp2[s][d]) % MOD
        dp2 = new
    ans = sum(dp2[n][d] for d in range(k+1) if d % 2 == k % 2) % MOD
    print(ans)

if __name__ == "__main__":
    solve()
